 const culture=id=>cultures.find(c=>c.id===id),clan=id=>clans.find(c=>c.id===id),path=id=>paths.find(p=>p.id===id);
 function given(s,slot=0){const c=culture(s.humanOrigin?.ethnicityId)||cultures[s.homeKingdom??s.kingdom],h=hash(s.seed,810+slot),m=hash(s.seed,1510+slot);return c.first[h%c.first.length]+c.first[(h>>>8)%c.first.length]+c.last[m%c.last.length]}
 function birth(s){if(s.race!==0)return;const local=cultures[s.kingdom],h=hash(s.seed,1810),ethnicity=h%100<72?local:cultures[(h>>>8)%cultures.length],secondary=hash(s.seed,1811)%100<22?cultures[(ethnicity.realm+1+hash(s.seed,1812)%(cultures.length-1))%cultures.length].id:null;
  const available=types.filter(t=>t.id!=='crown'||clans.some(c=>c.type==='crown'&&c.realm===s.kingdom));let n=hash(s.seed,1813)%available.reduce((a,t)=>a+t.weight,0),type=available.at(-1);for(const t of available){n-=t.weight;if(n<0){type=t;break}}let houses=clans.filter(c=>c.type===type.id);if(type.id==='crown')houses=houses.filter(c=>c.realm===s.kingdom);else{const localHouses=houses.filter(c=>c.realm===s.kingdom);if(localHouses.length&&hash(s.seed,1819)%100<78)houses=localHouses}const house=houses[hash(s.seed,1814)%houses.length];
  s.humanOrigin={version:1,ethnicityId:ethnicity.id,secondaryId:secondary,clanId:house.id,birthRank:house.rank,migrated:false,favor:60,path:'open',pathHistory:[],progress:Object.fromEntries(paths.map(p=>[p.id,0])),readyBio:12,lastQuarter:-1,lastBio:0,lastDaily:-1,supportYear:-1};s.gold=Math.max(0,s.gold+(house.rank-s.rank)*9+house.gift);s.rank=house.rank;const family=house.name+'-'+ethnicity.first[hash(s.seed,1815)%8]+ethnicity.last[hash(s.seed,1816)%8];s.identity={given:given(s),family,full:given(s)+' '+family,culture:'human-'+ethnicity.id};s.name=s.identity.full;s.look.complexion=hash(s.seed,1817)%6;
 }
 function ensure(s){if(s.race!==0)return null;if(!s.humanOrigin){const group=['ordinary','agrarian','artisan','merchant','mage','knight','noble','royal'][s.heritage?.birthRank??s.rank],houses=clans.filter(c=>c.type===group),house=houses[hash(s.seed,1814)%houses.length];s.humanOrigin={version:1,ethnicityId:cultures[s.homeKingdom??s.kingdom].id,secondaryId:null,clanId:house.id,birthRank:s.heritage?.birthRank??s.rank,migrated:true,favor:60,path:'open',pathHistory:[],progress:Object.fromEntries(paths.map(p=>[p.id,0])),readyBio:Math.max(12,Engine.biological(s)+.5),lastQuarter:-1,lastBio:Engine.biological(s),lastDaily:-1,supportYear:-1}}return s.humanOrigin}
 function decorate(s){const h=ensure(s);if(!h||h.migrated)return;const c=clan(h.clanId),t=types.find(t=>t.id===c.type);if(s.household){s.household.title='สกุล'+c.name;s.household.originNote=c.story+' · '+c.burden;for(const m of s.household.members){if(m.id==='guardian'||m.id.startsWith('parent-')){const i=m.id==='guardian'?0:1;m.occupation=m.adultOccupation=t.parents[i]}if(m.race===0)m.look.complexion=(s.look.complexion+(hash(s.seed,m.name.length)%3)-1+6)%6}}if(s.heritage){s.heritage.familyId=c.type==='merchant'?'merchantHouse':c.type==='mage'?'scholars':c.id==='human-house-16'?'hero':'ordinary';s.heritage.birthRank=s.rank;s.heritage.note=c.story;s.heritage.decorated=true}}
 function classLabel(s){if(s.race!==0&&typeof SpeciesSociety!=='undefined')return SpeciesSociety.label(s);if(typeof RaceDrives!=='undefined'&&RaceDrives.cashless(s))return RaceDrives.nativeRank(s);const h=s.humanOrigin;if(!h||h.migrated||s.rank!==h.birthRank)return CLASSES[s.rank];return types.find(t=>t.id===clan(h.clanId)?.type)?.label||CLASSES[s.rank]}
 function choosePath(s,id){const h=ensure(s);if(!h||!path(id)||h.path===id||s.dead||!s.accepted||s.calendar?.pending||s.outcome||Engine.biological(s)<12)return false;h.path=id;h.readyBio=Math.max(h.readyBio,Engine.biological(s)+.5);h.pathHistory.push({id,age:s.age});h.pathHistory=h.pathHistory.slice(-20);Narrative.append(s,{title:'เส้นทางที่อยากลอง · '+path(id).name,paragraphs:['คุณเลือกให้ช่วงต่อไปของชีวิตมีพื้นที่สำหรับ'+path(id).name+' '+path(id).description],kind:'decision',key:'human-path-'+id+'-'+s.calendar.count,scene:path(id).scene,tone:'important'});return true}
 function jobs(s,list){const h=s.humanOrigin;if(!h)return list;const p=path(h.path),pattern=p?new RegExp(p.pattern):/ผู้ช่วย|รับจ้าง|ชาวนา|ชาวสวน|ครัว|ช่างฝีมือฝึก|อาลักษณ์/;const pool=list.filter(({j})=>pattern.test(j[0]));return p?pool:(pool.length?pool:list)}
 function quarter(s){const h=ensure(s);if(!h||s.dead||!s.accepted||h.lastQuarter===s.calendar.count)return;h.lastQuarter=s.calendar.count;const now=Engine.biological(s),delta=Math.max(0,Math.min(1,now-h.lastBio));h.lastBio=now;const p=path(h.path);if(p&&delta&&now>=12&&now<=65&&s[p.stat]<85)s[p.stat]=Math.min(85,s[p.stat]+delta*.8)}
 function matches(s,e){const h=s.humanOrigin;if(e.humanOnly&&s.race!==0)return false;if(e.humanPickPath)return !!h&&h.path==='open';if(e.clanOnly)return !!h&&!h.migrated&&h.clanId===e.clanOnly;if(e.ethnicityOnly)return !!h&&(h.ethnicityId===e.ethnicityOnly||h.secondaryId===e.ethnicityOnly);if(e.humanPathOnly)return !!h&&h.path===e.humanPathOnly&&h.progress[e.humanPathOnly]===(e.humanStep||0)&&Engine.biological(s)>=h.readyBio;if(h&&!h.migrated&&Number.isInteger(e.rankOnly))return false;return true}
 function observe(s,e,c,ok){const h=ensure(s);if(!h)return;if(c.humanPath){h.path=c.humanPath;h.pathHistory.push({id:c.humanPath,age:s.age});h.pathHistory=h.pathHistory.slice(-20);h.readyBio=Engine.biological(s)+.5}if(typeof c.effect.clanFavor==='number')h.favor=clamp(h.favor+(ok?c.effect.clanFavor:0));if(e.humanPathOnly){h.progress[e.humanPathOnly]=Math.min(3,h.progress[e.humanPathOnly]+1);h.readyBio=Engine.biological(s)+2}}
 function daily(s){const h=ensure(s),bio=Engine.biological(s);if(!h||s.calendar.count%3!==1)return null;const c=culture(h.ethnicityId),house=clan(h.clanId),p=path(h.path),n=hash(s.seed,s.calendar.count+1900);let title,paragraphs,scene='kitchen';if(bio<4){title='เสียงที่คุ้นเคยในบ้าน';paragraphs=['คนในบ้านฮัมเพลงภาษา'+c.language+'ข้างที่นอน คุณเงียบฟังแล้วขยับตามมือที่ยื่นมา'];scene='nursery'}else if(bio<12){const lines=[['รสที่จำได้','คุณช่วยยกถ้วย'+c.food+'ไปที่โต๊ะ คนในบ้านบอกให้วางส่วนของคนที่ยังไม่กลับไว้ก่อน'],['คำที่ออกเสียงไม่เหมือนกัน','เพื่อนถามคำทักใน'+c.language+' คุณสอนทีละคำแล้วลองคำทักของบ้านเขาบ้าง'],['ของเล็กที่เก็บไว้','คนในสกุล'+house.name+'ชวนคุณดูของเก่าและเล่าว่าบ้านนี้เริ่มอยู่ที่ไหน'],['สิ่งที่บ้านทำทุกฤดู','วันนี้คนในบ้าน'+c.custom+' คุณลองทำตามและหัวเราะเมื่อทำไม่เหมือนครั้งแรก']];[title,...paragraphs]=lines[n%lines.length]}else if(p){const texts={adventure:['คุณผูกเชือกเส้นเดิมซ้ำจนทำได้แม้มือเย็น คนร่วมทีมช่วยทดสอบก่อนเก็บลงถุง','คุณเขียนชื่อคนที่ออกเดินทางด้วยกันไว้หลังแผนที่ แล้วเผื่อช่องให้เขียนวันที่กลับ'],farmer:['คุณขยี้เมล็ดแห้งในมือก่อนตัดสินใจว่าล็อตไหนควรเก็บหว่าน','ฝนลงข้างนา คุณยืนดูร่องน้ำกับเพื่อนบ้านก่อนตกลงว่าจะเปิดช่องไหน'],artisan:['ชิ้นงานวันนี้ยังมีรอยมือ คุณขัดมันเท่าที่จำเป็นโดยเก็บรูปทรงเดิมไว้','ลูกค้ากลับมาให้ดูว่าของที่คุณซ่อมยังใช้ได้ เขาจำวันที่มาส่งได้ดีกว่าคุณ'],merchant:['ลูกค้าประจำมาฝากข่าวจากอีกเมือง คุณจดรายการของที่เขาขาดก่อนดูราคา','คุณนับเงินซื้อของเข้าร้านแยกจากเงินที่จะนำกลับบ้าน คราวนี้บัญชีตรงกัน'],music:['คุณลองเล่นเพลงเก่าให้ช้าลง คนที่นั่งข้างเวทีร้องตามได้จนจบ','สายดนตรีขาดก่อนซ้อม เพื่อนยื่นสายสำรองให้แล้วบอกว่าเก็บมาเผื่อคุณ'],mage:['อักขระที่เคยทำให้ถ้วยร้าวเริ่มนิ่ง คุณจดว่าเปลี่ยนอะไรไปเพียงอย่างเดียว','คุณเก็บบทที่ยังใช้ไม่ได้ลงลิ้นชัก ก่อนกลับมาทบทวนพื้นฐานที่ช่วยคนในบ้านได้จริง'],knight:['คุณส่งเวรพร้อมบอกว่าประตูบ้านไหนยังเปิดรอคนกลับ คนผลัดต่อพยักหน้าจำ','คุณลับดาบเสร็จแล้วช่วยเพื่อนซ่อมสายเกราะ งานเงียบ ๆ กินเวลานานกว่าการฝึกประลอง'],scholar:['นักเรียนอ่านประโยคแรกได้เอง คุณรอให้เขาจบก่อนพลิกไปหน้าถัดไป','คุณพบคำในจดหมายเก่าที่ไม่มีในตำรา จึงไปถามผู้เฒ่าผู้ยังใช้คำนั้น'],healer:['คนไข้กลับมาพร้อมตะกร้าผลไม้ คุณดีใจเมื่อเห็นว่าเขาเดินขึ้นบันไดได้เอง','คุณวางถ้วยน้ำไว้ใกล้คนไข้ แล้วนั่งฟังอาการที่เขายังหาคำอธิบายไม่ได้'],home:['วันนี้คนในบ้านกลับถึงโต๊ะไม่พร้อมกัน คุณอุ่นซุปหม้อเดิมไว้ให้คนสุดท้าย','คุณช่วยเพื่อนบ้านยกชั้นไม้ หลังงานเสร็จจึงนั่งคุยกันจนลืมเวลา']};title='วันหนึ่งบนเส้นทาง'+p.name;paragraphs=[texts[p.id][n%2]];scene=p.scene}else{title='มื้อหนึ่งของบ้านสกุล'+house.name;paragraphs=['คุณกิน'+c.food+'กับคนในบ้าน ระหว่างเก็บถ้วยมีคนเล่าข่าวจาก'+KINGDOMS[house.realm][0]+'ซึ่งเป็นถิ่นเดิมของสกุล']}
 return {title,paragraphs,kind:'daily',key:'human-day-'+(p?.id||'home')+'-'+n%12,scene};}
 function preferredPath(s,style){const h=s.humanOrigin;if(!h)return null;if(style==='safe')return 'home';if(style==='kind')return 'healer';if(style==='ambitious')return hash(s.seed,1830)%2?'adventure':'mage';return {crown:'scholar',royal:'music',sovereign:'merchant',noble:'knight',knight:'knight',mage:'mage',merchant:'merchant',artisan:'artisan',agrarian:'farmer',ordinary:'home'}[clan(h.clanId).type]}
 function supportAmount(s){const c=clan(s.humanOrigin?.clanId);return c?Math.min(typeof Economy==='undefined'?1e9:Economy.ensure(s).familyFund*.1,Math.max(200,Math.round(c.gift/3)*100)):0}
 function canSupport(s){const h=s.humanOrigin,c=clan(h?.clanId);return !!h&&!h.migrated&&c.gift>0&&!s.dead&&s.accepted&&!s.calendar?.pending&&!s.outcome&&Engine.biological(s)>=16&&h.supportYear===-1&&h.favor>=40}
 function support(s){if(!canSupport(s))return false;const h=s.humanOrigin,c=clan(h.clanId),amount=supportAmount(s);h.supportYear=Math.floor(Engine.biological(s));h.favor-=12;s.gold=Math.min(1e9,s.gold+amount);if(typeof Economy!=='undefined')Economy.ensure(s).familyFund=Math.max(0,Economy.ensure(s).familyFund-amount);Narrative.append(s,{title:'ทุนเริ่มต้นจากบ้านสกุล'+c.name,paragraphs:['บ้านสกุล'+c.name+'มอบ '+amount+' ทองให้คุณเริ่มเส้นทางของตน คุณรับเงินพร้อมบอกว่าจะกลับมาเล่าให้ฟังว่านำไปใช้อย่างไร'],kind:'family',key:'human-family-support',tone:'important',scene:'kitchen'});return true}
 function valid(s){const h=s.humanOrigin;if(h===undefined)return true;const num=(n,a,b)=>Number.isFinite(n)&&n>=a&&n<=b,int=(n,a,b)=>Number.isInteger(n)&&num(n,a,b);return s.race===0&&h&&h.version===1&&!!culture(h.ethnicityId)&&(h.secondaryId===null||!!culture(h.secondaryId)&&h.secondaryId!==h.ethnicityId)&&!!clan(h.clanId)&&int(h.birthRank,0,7)&&typeof h.migrated==='boolean'&&num(h.favor,0,100)&&(h.path==='open'||!!path(h.path))&&Array.isArray(h.pathHistory)&&h.pathHistory.length<=20&&h.pathHistory.every(p=>p&&!!path(p.id)&&num(p.age,0,s.age))&&h.progress&&Object.keys(h.progress).length===paths.length&&paths.every(p=>int(h.progress[p.id],0,3))&&num(h.readyBio,0,20000)&&int(h.lastQuarter,-1,s.calendar?.count??0)&&num(h.lastBio,0,Engine.biological(s)+.001)&&int(h.lastDaily,-1,20000)&&int(h.supportYear,-1,10000)}
 return {cultures,types,clans,paths,birth,ensure,decorate,given,classLabel,choosePath,jobs,quarter,matches,observe,daily,valid,preferredPath,supportAmount,canSupport,support,culture,clan,path};
